// GL is now resolved INLINE per item in the item-create branch (no global static data),
// so this node only forwards the invoice payload so the customer/payment logic keeps working.
return $input.all();

// Get the input data
const inputData = $input.first().json;

// Check if there was an error from the HTTP request
if (inputData.error) {
  // Extract error details for logging
  const errorCode = inputData.error.code;
  const errorStatus = inputData.error.status;
  const errorMessage = inputData.error.message;

  // Check if it's a "customer not found" error (404 with NONEXISTENT_EXTERNAL_ID)
  const isNotFoundError = errorStatus === 404 && 
    (errorMessage.includes('NONEXISTENT_EXTERNAL_ID') || 
     errorMessage.includes('does not exist'));

  return {
    json: {
      customerExists: false,
      message: isNotFoundError 
        ? "Customer not found in NetSuite." 
        : "HTTP error occurred while checking customer",
      errorCode: errorCode,
      errorStatus: errorStatus,
      isNotFoundError: isNotFoundError
    }
  };
}

// Check if customer data exists
if (!inputData.data) {
  // Return a flag indicating no customer exists
  return {
    json: {
      customerExists: false,
      message: "No customer data returned from NetSuite"
    }
  };
}

try {
  // Parse the JSON string from the data field
  const customerData = JSON.parse(inputData.data);

  // Extract and flatten the important customer information
  const flattenedCustomer = {
    // IDs and Basic Info
    internalId: customerData.id,
    externalId: customerData.externalId,
    entityId: customerData.entityId,
    customerId: customerData.custentity4,

    // Personal Info
    firstName: customerData.firstName,
    lastName: customerData.lastName,
    isPerson: customerData.isPerson,
    email: customerData.email,

    // Address
    defaultAddress: customerData.defaultAddress,

    // Status and Settings
    isInactive: customerData.isInactive,
    entityStatus: {
      id: customerData.entityStatus.id,
      name: customerData.entityStatus.refName
    },

    // Financial Info
    balance: customerData.balance,
    overdueBalance: customerData.overdueBalance,
    daysOverdue: customerData.daysOverdue,
    depositBalance: customerData.depositBalance,
    unbilledOrders: customerData.unbilledOrders,

    // Aging
    aging: customerData.aging,
    aging1: customerData.aging1,
    aging2: customerData.aging2,
    aging3: customerData.aging3,
    aging4: customerData.aging4,

    // Currency
    currency: {
      id: customerData.currency.id,
      code: customerData.currency.refName
    },

    // Subsidiary
    subsidiary: {
      id: customerData.subsidiary.id,
      name: customerData.subsidiary.refName
    },

    // Accounts
    receivablesAccount: {
      id: customerData.receivablesAccount.id,
      name: customerData.receivablesAccount.refName
    },
    drAccount: {
      id: customerData.drAccount.id,
      name: customerData.drAccount.refName
    },

    // Dates
    dateCreated: customerData.dateCreated,
    lastModifiedDate: customerData.lastModifiedDate,

    // Preferences
    emailPreference: customerData.emailPreference.refName,
    emailTransactions: customerData.emailTransactions,
    printTransactions: customerData.printTransactions,
    unsubscribe: customerData.unsubscribe,

    // Shipping
    shippingCarrier: customerData.shippingCarrier.refName,
    shipComplete: customerData.shipComplete,

    // Custom Fields
    customFields: {
      customerRefund: customerData.custentity_2663_customer_refund,
      directDebit: customerData.custentity_2663_direct_debit,
      customerProbability: customerData.custentity_atlas_customer_probability,
      orderLeadTime: customerData.custentity_c360_entity_order_lead_time,
      needsApproval: customerData.custentity_naw_trans_need_approval
    }
  };

  // Return the flattened data with customerExists flag
  return { 
    json: {
      customerExists: true,
      flattenedCustomer,
      originalData: customerData
    }
  };

} catch (error) {
  // If parsing fails, return error flag
  return {
    json: {
      customerExists: false,
      message: "Error parsing customer data",
      error: error.message
    }
  };
}

