// ----------------------
// 1. Get ALL item check results from the input
// ----------------------
let suiteqlItems = [];

// The check_if_item_exist node outputs multiple items, get them all
const allInputs = $input.all();

// Extract the itemData from each input
allInputs.forEach(input => {
    if (input.json && input.json.itemData) {
        suiteqlItems.push(input.json.itemData);
    }
});

// If no items found via input, fall back to parsing from get_item_internal_id_by_quering
if (suiteqlItems.length === 0) {
    const suiteqlNodeData = $('get_item_internal_id_by_quering').all();

    suiteqlNodeData.forEach(nodeData => {
        if (nodeData.json && nodeData.json.data) {
            try {
                const parsed = JSON.parse(nodeData.json.data);
                const items = parsed.items || [];
                suiteqlItems.push(...items);
            } catch (err) {
                console.error("Error parsing SuiteQL data:", err);
            }
        }
    });
}

// ----------------------
// 2. Get Zoho invoice
// ----------------------
const zohoInvoice = $node["Get Specific Invoice from Zoho Billing"].json.invoice || {};

// ----------------------
// 3. Get NetSuite customer
// ----------------------
const netsuiteCustomer = $node["flat_customer"].json.flattenedCustomer || {};

// ----------------------
// 4. Flatten Zoho invoice & map line items
// ----------------------
// ----------------------
// Line level discount helper (display only)
// Zoho already folds a line discount into item_total. To make the discount
// visible on the NetSuite invoice, the original line is restored to its full
// amount and the discount follows as its own negative line against the same
// item. Lines without a discount are built exactly as they were before.
// ----------------------
const round2 = (value) => Math.round((Number(value) || 0) * 100) / 100;

function resolveLineDiscount(line, grossAmount) {
    // Zoho nets a LINE discount into item_total, so a discounted line shows a
    // total below quantity times rate. An OVERALL invoice discount is apportioned
    // onto the lines but left out of item_total, so a line whose total still
    // equals quantity times rate carries no line discount of its own and must
    // not get a negative line here. That case is picked up as an invoice level
    // discount below and mapped to the NetSuite Discount Item field instead.
    const netTotal = round2(line.total ?? line.item_total ?? grossAmount);
    const derived = round2(grossAmount - netTotal);
    if (derived <= 0) {
        return 0;
    }

    // Zoho's explicit discount amount, when it agrees with the netted total.
    const explicit = Number(line.discount_amount ?? line.discount_total ?? 0);
    if (explicit > 0 && Math.abs(round2(explicit) - derived) <= 0.01) {
        return round2(explicit);
    }

    // Otherwise the gap between the full line amount and Zoho's net total.
    return derived;
}

const flattenedInvoice = {
    invoiceNumber: zohoInvoice.invoice_number || zohoInvoice.number || "",
    invoiceId: zohoInvoice.invoice_id || "",
    invoiceDate: zohoInvoice.invoice_date || zohoInvoice.date || "",
    dueDate: zohoInvoice.due_date || "",
    total: zohoInvoice.total || 0,
    balance: zohoInvoice.balance || 0,
    notes: zohoInvoice.notes || "",
    lineItems: (zohoInvoice.invoice_items || []).flatMap(line => {
        // Find matching NetSuite item by name
        const itemName = line.name || line.description || "";
        const netsuiteItem = suiteqlItems.find(i => 
            String(i.displayname||"").trim().toLowerCase() === String(itemName||"").trim().toLowerCase() || String(i.itemid||"").trim().toLowerCase() === String(itemName||"").trim().toLowerCase()
        );

        const quantity = line.quantity || 1;
        const price = line.price || line.rate || 0;
        const netTotal = line.total || line.item_total || 0;
        const grossAmount = round2(quantity * price);
        const discountAmount = resolveLineDiscount(line, grossAmount);

        const baseLine = {
            name: itemName,
            quantity: quantity,
            price: price,
            // Discounted lines show the full amount, the discount follows below.
            item_total: discountAmount > 0 ? grossAmount : netTotal,
            zohoItemId: line.item_id || line.product_id || "",
            netsuiteInternalId: netsuiteItem ? netsuiteItem.id : null,
            displayName: netsuiteItem ? netsuiteItem.displayname : ""
        };

        if (discountAmount <= 0) {
            return [baseLine];
        }

        // Same item and same description, quantity 1 at a negative rate, placed
        // immediately after the line it discounts.
        return [baseLine, {
            ...baseLine,
            quantity: 1,
            price: -discountAmount,
            item_total: -discountAmount,
            isDiscountLine: true
        }];
    })
};

// ----------------------
// Overall invoice discount
// Zoho spreads a header discount across the lines but leaves item_total alone,
// which is why those lines are deliberately not discounted above. The gap
// between the line subtotal and the invoice total is that header discount.
// NetSuite takes it on the Discount Item field rather than as invoice lines,
// so the line level discount behaviour is completely unaffected.
// ----------------------
function resolveInvoiceDiscount(invoice, lineSubtotal) {
    const invoiceTotal = round2(invoice.total ?? lineSubtotal);
    const derived = round2(lineSubtotal - invoiceTotal);
    if (derived <= 0) {
        return null;
    }

    // NetSuite types discountrate as a Number over REST and rejects a string
    // such as "-70%". The discount therefore always travels as a negative
    // currency amount. A percentage discount in Zoho is already resolved into
    // that amount by the gap between the line subtotal and the invoice total,
    // so the invoice still lands on exactly the total Zoho holds.
    return { rate: -derived, amount: derived };
}

const lineSubtotal = round2(
    (flattenedInvoice.lineItems || []).reduce((sum, line) => sum + (Number(line.item_total) || 0), 0)
);
flattenedInvoice.overallDiscount = resolveInvoiceDiscount(zohoInvoice, lineSubtotal);

// ----------------------
// 5. Build NetSuite payload
// ----------------------
const netsuitePayload = {
    externalId: flattenedInvoice.invoiceId,
    tranid: flattenedInvoice.invoiceNumber,
    entity: { id: netsuiteCustomer.internalId || "" },
    tranDate: flattenedInvoice.invoiceDate,
    dueDate: flattenedInvoice.dueDate,
    memo: flattenedInvoice.notes || `Invoice from Zoho: ${flattenedInvoice.invoiceNumber}`,
    currency: { id: netsuiteCustomer.currency?.id || "1" },
    subsidiary: { id: "1" },
    item: {
        items: flattenedInvoice.lineItems.map(line => ({
            item: {
                id: line.netsuiteInternalId
            },
            quantity: line.quantity,
            rate: line.price,
            amount: line.item_total,
            description: line.name
        }))
    }
};

// ----------------------
// 6. Return final output
// ----------------------
return {
    json: {
        flattenedInvoice,
        netsuitePayload,
        customer: netsuiteCustomer,
        suiteqlItems
    }
};

// Input: JSON with flattenedInvoice (which has enriched lineItems with netsuiteInternalId)
const flattenedInvoice = $json.flattenedInvoice;
const customer = $json.customer;

// Overall invoice discount, already resolved in the prepare_payload node.
// Line level discounts are separate and already sit in lineItems as their own
// negative lines, so nothing about them changes here.
const NETSUITE_DISCOUNT_ITEM_ID = "11914";
const overallDiscount = flattenedInvoice.overallDiscount || null;

// Build line items for NetSuite using the ENRICHED line items
const lineItems = (flattenedInvoice.lineItems || []).map(line => ({
    item: { 
        id: line.netsuiteInternalId
    },
    quantity: line.quantity,
    rate: line.price,
    amount: line.item_total,
    description: line.name
}));

return {
  json: {
    netsuitePayload: {
      externalId: flattenedInvoice.invoiceNumber,  // Set to invoice number (e.g., "Test-002")
      tranid: flattenedInvoice.invoiceNumber,      // Document number - same as externalId
      entity: { id: customer.internalId },
      tranDate: flattenedInvoice.invoiceDate,
      dueDate: flattenedInvoice.dueDate,
      currency: { id: customer.currency?.id || "1" },
      subsidiary: { id: "1" },
      item: { items: lineItems },
      ...(overallDiscount
        ? { discountitem: { id: NETSUITE_DISCOUNT_ITEM_ID }, discountrate: overallDiscount.rate }
        : {})
    }
  }
};

// Get both the Zoho invoice and NetSuite customer data
const zohoInvoice = $('Get Specific Invoice from Zoho Billing').first().json.invoice;
const netsuiteCustomer = $input.first().json.flattenedCustomer;

// Helper function: Convert date from yyyy-mm-dd to mm/dd/yyyy
function convertDateFormat(dateString) {
  if (!dateString) return null;
  const [year, month, day] = dateString.split('-');
  return `${month}/${day}/${year}`;
}

// Flatten the Zoho invoice data
const flattenedInvoice = {
  // Invoice identification
  invoiceNumber: zohoInvoice.invoice_number || zohoInvoice.number,
  invoiceId: zohoInvoice.invoice_id,

  // Customer info (from NetSuite)
  customerInternalId: netsuiteCustomer.internalId,
  customerExternalId: netsuiteCustomer.externalId,
  customerName: netsuiteCustomer.firstName + ' ' + netsuiteCustomer.lastName,
  customerEmail: netsuiteCustomer.email,

  // Dates
  invoiceDate: zohoInvoice.invoice_date || zohoInvoice.date,
  dueDate: zohoInvoice.due_date,

  // Financial
  total: zohoInvoice.total,
  balance: zohoInvoice.balance,
  currencyCode: zohoInvoice.currency_code,

  // Status
  status: zohoInvoice.status,

  // Line items
  lineItems: zohoInvoice.invoice_items || [],

  // Additional info
  referenceNumber: zohoInvoice.reference_number || '',
  notes: zohoInvoice.notes || '',
  terms: zohoInvoice.payment_terms || 0,
  termsLabel: zohoInvoice.payment_terms_label || 'Net 30'
};

// Build NetSuite Invoice Payload
const netsuitePayload = {
  // Invoice number as external ID
  externalId: flattenedInvoice.invoiceNumber,

  // Customer reference - use internal ID (more reliable than external ID)
  entity: {
    id: netsuiteCustomer.internalId
  },

  // Invoice date
  tranDate: convertDateFormat(flattenedInvoice.invoiceDate),

  // Due date (optional)
  dueDate: convertDateFormat(flattenedInvoice.dueDate),

  // Line items
  item: {
    items: flattenedInvoice.lineItems.map(item => ({
      item: {
        externalId: item.item_code || item.code
      },
      quantity: item.quantity || 1,
      rate: item.rate || item.price || 0,
      amount: item.item_total || item.total || 0,
      description: item.description || item.name || ''
    }))
  },

  // Memo/Notes
  memo: flattenedInvoice.notes || `Invoice from Zoho: ${flattenedInvoice.invoiceNumber}`,

  // Currency
  currency: {
    id: netsuiteCustomer.currency.id
  },

  // Subsidiary (from customer)
  subsidiary: {
    id: netsuiteCustomer.subsidiary.id
  }
};

// Return both flattened invoice and NetSuite payload
return {
  json: {
    flattenedInvoice,
    netsuitePayload,
    // Keep customer data for reference
    customer: netsuiteCustomer
  }
};

// Get the Zoho invoice data from the previous node in the flow
const inputData = $input.first().json;

// Try to get invoice from multiple possible sources
let zohoInvoice;

// Option 1: Check if invoice is in the input
if (inputData.invoice) {
  zohoInvoice = inputData.invoice;
}
// Option 2: Try to get from the named node
else {
  try {
    const invoiceData = $('Get Specific Invoice from Zoho Billing').first().json;

    if (invoiceData.invoice) {
      zohoInvoice = invoiceData.invoice;
    } else {
      zohoInvoice = invoiceData;
    }
  } catch (error) {
    throw new Error('Could not access Zoho invoice data. Please ensure invoice data is passed through the workflow.');
  }
}

function limitText(value, maxLength) {
  const text = String(value || '').trim();
  return text.length > maxLength ? text.slice(0, maxLength) : text;
}

// NetSuite person-name fields are capped at 32 chars.
function splitName(fullName) {
  const cleanName = String(fullName || '').trim().replace(/\s+/g, ' ');
  if (!cleanName) return { firstName: 'Unknown', lastName: 'Customer' };

  const nameParts = cleanName.split(' ');
  if (nameParts.length === 1) {
    return { firstName: limitText(nameParts[0], 32), lastName: 'Unknown' };
  }

  return {
    firstName: limitText(nameParts[0], 32),
    lastName: limitText(nameParts.slice(1).join(' '), 32)
  };
}

// Extract customer info from Zoho invoice
const customerName = zohoInvoice.customer_name || '';
const { firstName, lastName } = splitName(customerName);

// Get phone from multiple possible locations
const phone = zohoInvoice.billing_address?.phone || 
              (zohoInvoice.contactpersons && zohoInvoice.contactpersons[0]?.mobile) ||
              (zohoInvoice.contactpersons && zohoInvoice.contactpersons[0]?.phone) ||
              '';

// Get contact_number (this will be the externalId)
const contactNumber = zohoInvoice.contact_number || zohoInvoice.customer_id || '';

// Get billing address details
const billingAddress = zohoInvoice.billing_address || {};
const addressLine1 = billingAddress.address || billingAddress.street || '';
const city = billingAddress.city || '';
const state = billingAddress.state || '';
const zip = billingAddress.zip || billingAddress.postal_code || '';

// Build address label: "Customer Name - Primary Address"
const addressLabel = limitText(`${customerName} - Primary Address`, 80);

// Build the entity ID with format: "CUS-04356 Tyler Green"
const entityId = limitText(`${contactNumber} ${customerName}`, 83);

// Build the NetSuite customer creation payload
const netsuiteCustomerPayload = {
  // Required: Name fields
  firstName: firstName,
  lastName: lastName || 'Unknown',

  // Required: Person flag
  isPerson: true,

  // Required: Subsidiary
  subsidiary: {
    id: "1"
  },

  // External ID - use contact_number (e.g., "CUS-04356")
  externalId: contactNumber,

  // Entity ID - Customer ID with name format: "CUS-04356 Tyler Green"
  entityId: entityId,

  // Email
  email: zohoInvoice.email || '',

  // Phone
  phone: phone,

  // Entity Status
  entityStatus: {
    id: "13"
  },

  // Currency
  currency: {
    id: "1"
  },

  // Custom field: Zoho Customer ID
  custentity4: contactNumber,

  // Address configuration - USA with ISO country code
  addressBook: {
    items: [
      {
        defaultBilling: true,
        defaultShipping: true,
        label: addressLabel,
        addressBookAddress: {
          country: {
            id: "US"
          },
          addr1: addressLine1 || '',
          city: city || '',
          state: state || '',
          zip: zip || '',
          addrPhone: phone || ''
        }
      }
    ]
  }
};

// Return the payload ready for HTTP POST
return {
  json: {
    customerPayload: netsuiteCustomerPayload,
    contactNumber: contactNumber,
    // Keep original data for reference
    zohoCustomerInfo: {
      customerName: customerName,
      contactNumber: contactNumber,
      customerId: zohoInvoice.customer_id,
      email: zohoInvoice.email,
      phone: phone,
      invoiceNumber: zohoInvoice.invoice_number,
      billingAddress: billingAddress,
      addressLabel: addressLabel,
      entityId: entityId,
      originalEntityId: `${contactNumber} ${customerName}`
    }
  }
};

