// ----------------------
// 1. Get ALL item check results from the input
// ----------------------
let suiteqlItems = [];

// The check_if_item_exist1 node outputs multiple items, get them all
const allInputs = $input.all();

// Extract the itemData from each input
allInputs.forEach(input => {
    if (input.json && input.json.itemData) {
        suiteqlItems.push(input.json.itemData);
    }
});

// If no items found via input, fall back to parsing from get_item_internal_id_by_quering2
if (suiteqlItems.length === 0) {
    const suiteqlNodeData = $('get_item_internal_id_by_quering2').all();

    suiteqlNodeData.forEach(nodeData => {
        if (nodeData.json && nodeData.json.data) {
            try {
                const parsed = JSON.parse(nodeData.json.data);
                const items = parsed.items || [];
                suiteqlItems.push(...items);
            } catch (err) {
                console.error("Error parsing SuiteQL data:", err);
            }
        }
    });
}

// ----------------------
// 2. Get Zoho invoice
// ----------------------
const zohoInvoice = $node["Get Specific Invoice from Zoho Billing"].json.invoice || {};

// ----------------------
// 3. Get NetSuite customer from flatten_data.all2
// ----------------------
const netsuiteCustomer = $node["flatten_data.all2"].json.customer || {};

// Verify customer has internalId
if (!netsuiteCustomer.internalId) {
    throw new Error("Customer internalId missing from flatten_data.all2");
}

console.log("Customer Internal ID:", netsuiteCustomer.internalId);

// ----------------------
// 4. Flatten Zoho invoice & map line items
// ----------------------
// ----------------------
// Line level discount helper (display only)
// Zoho already folds a line discount into item_total. To make the discount
// visible on the NetSuite invoice, the original line is restored to its full
// amount and the discount follows as its own negative line against the same
// item. Lines without a discount are built exactly as they were before.
// ----------------------
const round2 = (value) => Math.round((Number(value) || 0) * 100) / 100;

function resolveLineDiscount(line, grossAmount) {
    // Zoho nets a LINE discount into item_total, so a discounted line shows a
    // total below quantity times rate. An OVERALL invoice discount is apportioned
    // onto the lines but left out of item_total, so a line whose total still
    // equals quantity times rate carries no line discount of its own and must
    // not get a negative line here. That case is picked up as an invoice level
    // discount below and mapped to the NetSuite Discount Item field instead.
    const netTotal = round2(line.total ?? line.item_total ?? grossAmount);
    const derived = round2(grossAmount - netTotal);
    if (derived <= 0) {
        return 0;
    }

    // Zoho's explicit discount amount, when it agrees with the netted total.
    const explicit = Number(line.discount_amount ?? line.discount_total ?? 0);
    if (explicit > 0 && Math.abs(round2(explicit) - derived) <= 0.01) {
        return round2(explicit);
    }

    // Otherwise the gap between the full line amount and Zoho's net total.
    return derived;
}

const flattenedInvoice = {
    invoiceNumber: zohoInvoice.invoice_number || zohoInvoice.number || "",
    invoiceId: zohoInvoice.invoice_id || "",
    invoiceDate: zohoInvoice.invoice_date || zohoInvoice.date || "",
    dueDate: zohoInvoice.due_date || "",
    total: zohoInvoice.total || 0,
    balance: zohoInvoice.balance || 0,
    notes: zohoInvoice.notes || "",
    lineItems: (zohoInvoice.invoice_items || []).flatMap(line => {
        // Find matching NetSuite item by name
        const itemName = line.name || line.description || "";
        const netsuiteItem = suiteqlItems.find(i => 
            String(i.displayname||"").trim().toLowerCase() === String(itemName||"").trim().toLowerCase() || String(i.itemid||"").trim().toLowerCase() === String(itemName||"").trim().toLowerCase()
        );

        const quantity = line.quantity || 1;
        const price = line.price || line.rate || 0;
        const netTotal = line.total || line.item_total || 0;
        const grossAmount = round2(quantity * price);
        const discountAmount = resolveLineDiscount(line, grossAmount);

        const baseLine = {
            name: itemName,
            quantity: quantity,
            price: price,
            // Discounted lines show the full amount, the discount follows below.
            item_total: discountAmount > 0 ? grossAmount : netTotal,
            zohoItemId: line.item_id || line.product_id || "",
            netsuiteInternalId: netsuiteItem ? netsuiteItem.id : null,
            displayName: netsuiteItem ? netsuiteItem.displayname : ""
        };

        if (discountAmount <= 0) {
            return [baseLine];
        }

        // Same item and same description, quantity 1 at a negative rate, placed
        // immediately after the line it discounts.
        return [baseLine, {
            ...baseLine,
            quantity: 1,
            price: -discountAmount,
            item_total: -discountAmount,
            isDiscountLine: true
        }];
    })
};

// ----------------------
// Overall invoice discount
// Zoho spreads a header discount across the lines but leaves item_total alone,
// which is why those lines are deliberately not discounted above. The gap
// between the line subtotal and the invoice total is that header discount.
// NetSuite takes it on the Discount Item field rather than as invoice lines,
// so the line level discount behaviour is completely unaffected.
// ----------------------
function resolveInvoiceDiscount(invoice, lineSubtotal) {
    const invoiceTotal = round2(invoice.total ?? lineSubtotal);
    const derived = round2(lineSubtotal - invoiceTotal);
    if (derived <= 0) {
        return null;
    }

    // NetSuite types discountrate as a Number over REST and rejects a string
    // such as "-70%". The discount therefore always travels as a negative
    // currency amount. A percentage discount in Zoho is already resolved into
    // that amount by the gap between the line subtotal and the invoice total,
    // so the invoice still lands on exactly the total Zoho holds.
    return { rate: -derived, amount: derived };
}

const lineSubtotal = round2(
    (flattenedInvoice.lineItems || []).reduce((sum, line) => sum + (Number(line.item_total) || 0), 0)
);
flattenedInvoice.overallDiscount = resolveInvoiceDiscount(zohoInvoice, lineSubtotal);

