const originalItemName = cleanText($json.itemName || item.displayName || originalZohoDetails.name || 'Zoho Item');

item.itemId = cleanItemId(item.itemId || originalZohoDetails.code || originalItemName);
item.displayName = originalItemName;
item.includeChildren = true;
item.salesDescription = cleanText(item.salesDescription || originalZohoDetails.description || originalItemName);
if (!item.externalId) {
  const externalSource = cleanText(originalZohoDetails.code || originalZohoDetails.product_id || originalZohoDetails.item_id || item.itemId);
  item.externalId = ('zoho_item_' + externalSource).replace(/[^a-zA-Z0-9_-]/g, '_').substring(0, 100);
}

delete item.taxSchedule;
delete item.itemName;

return {
  json: {
    itemPayload: item,
    itemExists: $json.itemExists,
    itemData: $json.itemData,
    itemName: originalItemName,
    zohoItemDetails: { ...originalZohoDetails, name: originalItemName }
  }
};

