// Get ALL SuiteQL responses (one for each item we queried)
const allSuiteqlResponses = $input.all();

// Get the original item data from reference_previous_data
const referenceData = $('reference_previous_data').all();

function cleanText(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

// Process each response
const results = [];

allSuiteqlResponses.forEach((response, index) => {
  const suiteqlResponse = response.json;
  let itemExists = false;
  let itemData = null;
  let itemInactive = false;

  if (suiteqlResponse && suiteqlResponse.data) {
    try {
      const parsed = JSON.parse(suiteqlResponse.data);
      const items = parsed.items || [];

      if (items.length > 0) {
        // Prefer an active match. An inactive item still counts as existing,
        // because NetSuite blocks a new item with the same name either way.
        const activeItems = items.filter(it => String(it.isinactive).toUpperCase() !== 'T' && it.isinactive !== true);
        itemExists = true;
        itemData = activeItems[0] || items[0];
        itemInactive = activeItems.length === 0;
      }
    } catch (err) {
      console.error("Error parsing SuiteQL data:", err);
    }
  }

  // Get the corresponding item data
  const originalItem = referenceData[index]?.json || {};
  const currentLineItem = originalItem.currentLineItem || {};
  const zohoItemDetails = {
    ...currentLineItem,
    name: cleanText(originalItem.itemName || currentLineItem.name || currentLineItem.description || '')
  };

  results.push({
    json: {
      itemExists: itemExists,
      itemData: itemData,
      itemInactive: itemInactive,
      itemName: zohoItemDetails.name,
      zohoItemDetails: zohoItemDetails
    }
  });
});

return results;

// Access the output from flatten_data.all node from anywhere in the workflow
const flattenDataOutput = $node["flatten_data.all"].json;

// Return the complete output
return {
  json: flattenDataOutput
};

// Access all outputs from get_seaprate_item node
const allItems = $('get_seaprate_item').all();

// Return all items
return allItems;

// Get the input data
const inputData = $input.first().json;

// Initialize default values
let problemIdentified = "Unknown error occurred";
let hasError = false;
let errorCode = null;

// Check if error exists
if (inputData.error) {
  hasError = true;
  const errorMessage = inputData.error.message || "";

  // Try to extract the nested error details from the message
  try {
    // The message contains escaped JSON, so we need to parse it
    const messageMatch = errorMessage.match(/\{.*\}/s);

    if (messageMatch) {
      // Clean up the escaped JSON
      const cleanedJson = messageMatch[0]
        .replace(/\\"/g, '"')
        .replace(/\\n/g, '');

      const parsedError = JSON.parse(cleanedJson);

      // Extract the actual error detail
      if (parsedError["o:errorDetails"] && parsedError["o:errorDetails"].length > 0) {
        problemIdentified = parsedError["o:errorDetails"][0].detail;
      } else if (parsedError.title) {
        problemIdentified = parsedError.title;
      }
    } else {
      // If we can't parse nested JSON, use the error message directly
      problemIdentified = errorMessage;
    }
  } catch (parseError) {
    // If parsing fails, use the original error message
    problemIdentified = errorMessage;
  }

  // Extract error code if available
  if (inputData.error.code) {
    errorCode = inputData.error.code;
