// ---- GL matching helpers: Zoho cf_netsuite_g_l_account -> NetSuite Income account ----
function normGl(s) {
  return String(s == null ? '' : s).replace(/\s*:\s*/g, ':').replace(/\s+/g, ' ').trim().toLowerCase();
}
function matchNsAccount(zohoGlValue, nsAccounts) {
  const raw = String(zohoGlValue == null ? '' : zohoGlValue).trim();
  if (!raw) return null;
  const m = raw.match(/^(\d+)\s+(.*)$/);
  const zNum = m ? m[1].trim() : (/^\d+$/.test(raw) ? raw : null);
