function getInvoice() {
  // .item is unavailable in 'Run Once for All Items' mode; fall back to the
  // current loop iteration's data (batch size is 1, so .first() is this invoice).
  try {
    const inv = $('Get Specific Invoice from Zoho Billing').item.json.invoice;
    if (inv && (inv.invoice_number || inv.invoice_id)) return inv;
  } catch (e) {}
  try {
    const inv = $('Get Specific Invoice from Zoho Billing').first().json.invoice;
    if (inv && (inv.invoice_number || inv.invoice_id)) return inv;
