    return $('get_invoice_by_invoice_number').first().json.invoices[0] || {};
  } catch (e) { return {}; }
}

function invoiceKey(invoiceNumber, fallback) {
  return String(invoiceNumber || fallback || '').trim();
}

function hasFailedLogged(key) {
  if (!key) return false;
  if (staticData.invoiceReport.failedInvoiceNumbers[key]) return true;
  return staticData.invoiceReport.rows.some(row => {
    const rowKey = invoiceKey(row.invoiceNumber, row.invoiceId || row.customerNumber);
    const cat = String(row.category || '').toLowerCase();
    return rowKey === key && (row.status === 'ERROR' || cat === 'failed');
  });
}

function hasDuplicateLogged(key) {
  if (!key) return false;
  if (staticData.invoiceReport.duplicateInvoiceNumbers[key]) return true;
