    const rowKey = invoiceKey(row.invoiceNumber, row.invoiceId || row.customerNumber);
    const cat = String(row.category || '').toLowerCase();
    return rowKey === key && (row.status === 'SKIPPED' || cat.includes('duplicate'));
  });
}

function removeNonDuplicateRowsForInvoice(key) {
  if (!key) return;
