    const cat = String(row.category || '').toLowerCase();
    return row.status === 'SKIPPED' || cat.includes('duplicate');
  });
  delete staticData.invoiceReport.failedInvoiceNumbers[key];
}

function extractErrorMessage(input) {
  const err = input.error;
  if (err && typeof err === 'object') return err.message || JSON.stringify(err);
  if (err) return String(err);
  return String(input.message || input.error_type || input.friendlyMessage || 'Zoho custom field update failed.');
}

function shortReasonFrom(rawMsg) {
  const raw = String(rawMsg || '');
  const lower = raw.toLowerCase();
  if (lower.includes('already exists') || lower.includes('duplicate')) return 'Record already exists';
