function getCategory(row) {
  const cat = String(row.category || '').toLowerCase();
  if (cat.includes('skipped') || cat.includes('duplicate') || row.status === 'SKIPPED') return 'Skipped Duplicates';
  if (row.status === 'SUCCESS' || cat === 'created') return 'Created';
  return 'Failed';
}

function invoiceKey(row) {
  return String(row.invoiceNumber || row.invoiceId || row.customerNumber || '').trim();
}

function shouldReplace(existing, candidate) {
  if (!existing) return true;
  const existingCategory = getCategory(existing);
  const candidateCategory = getCategory(candidate);

  // Duplicate errors take preference over every other row for the same invoice.
  if (existingCategory === 'Skipped Duplicates') return false;
  if (candidateCategory === 'Skipped Duplicates') return true;

  // After duplicate preference, keep the first non-duplicate failure.
  if (existingCategory === 'Failed') return false;
  if (candidateCategory === 'Failed') return true;

  const priority = { 'Created': 1 };
  return (priority[candidateCategory] || 0) > (priority[existingCategory] || 0);
}

