function cleanText(value, maxLength) { maxLength = maxLength || 300; if (value === null || value === undefined) return ''; const text = String(value); return text.length > maxLength ? text.slice(0, maxLength) : text; }
function getCategory(row) { return row.normalizedCategory || row.category || 'Failed'; }
const exceptionRows = uniqueRows.filter(row => getCategory(row) !== 'Created');
return exceptionRows.map(row => {
  const category = getCategory(row);
  const invoiceNum = row.invoiceNumber || '';
  const customerNum = [row.customerNumber, row.customerName].filter(Boolean).join(' ');
  const amount = Number(row.amount || 0);
  const recordName = invoiceNum ? invoiceNum + ' - ' + category : 'Unknown - ' + category;
  const childExternalId = 'INVOICE_CHILD_' + execId + '_' + String(invoiceNum).replace(/[^a-zA-Z0-9]/g,'') + '_' + String(category).replace(/[^a-zA-Z0-9]/g,'');
  const childPayload = {
    externalId: childExternalId,
    name: cleanText(recordName, 80),
    custrecordcustrecordial_report: { id: String(parentId) },
    custrecordcustrecordial_category: cleanText(category, 300),
    custrecordcustrecordial_invoice: cleanText(invoiceNum, 300),
    custrecordcustrecordial_customer: cleanText(customerNum, 300),
    custrecordcustrecordial_amount: amount,
    custrecordcustrecordial_stage: cleanText(row.stage || 'Workflow Processing', 300),
    custrecordcustrecordial_message: cleanText(row.message || '', 1000),
    custrecordcustrecordial_totalamount: amount
  };
  return { json: { childPayload, parentId: String(parentId) } };
});

